// Build the claim-code DM for the property owner.
const t = $('When Called by WF10').first().json;
const a = $input.first().json;

const text = [
  `\u{1F3E0} Lead directo para ti \u2014 ${t.property_title || 'tu propiedad'}`,
  `\u{1F4B0} ${t.property_price || 'Precio por confirmar'}`,
  `\u{1F464} Lead: ${t.lead_name || 'Sin nombre'}`,
  ``,
  `Eres el asesor de esta propiedad. Responde *TOMO-${a.short_code}* en los proximos 2 min para tomarlo.`,
  `Si no respondes, pasara a la guardia.`
].join('\n');

return [{
  json: {
    number: t.owner_number,
    text,
    auction_id: a.auction_id,
    short_code: a.short_code,
    conversation_id: t.conversation_id,
    agent_id: t.owner_agent_id
  }
}];
